SourceCode.Declaration:
/// <summary>
/// Per-worker Menu access: which handheld modules a worker may use.
///
/// **An allow list once a worker has rows.** A worker with no rows at all keeps every normal
/// module (so nobody loses access before an admin sets them up); once a worker has any row, only
/// the modules ticked Allowed show in the app. The order modules (PO creation, TO creation, PO
/// confirmation) always need an Allowed row. The app applies the same rule - see
/// WarehouseWorkflow.kt, blockedWorkflows.
///
/// Modeled directly on HSMobileOpsUserWarehouse - a small per-user child table, one row per
/// thing being assigned - rather than a new mechanism.
/// </summary>
public class HSMobileOpsUserModulePermission extends common
{
}

Method.Source:
/// <summary>
/// Whether a worker may use a module under the allow-list rule (see the class doc): with no
/// rows at all, every module but the order modules; with rows, only those ticked Allowed.
/// </summary>
public static boolean isAllowed(RefRecId _userRecId, HSMobileOpsModule _module)
{
    HSMobileOpsUserModulePermission permission;
    HSMobileOpsUserModulePermission anyRow;

    select firstOnly IsAllowed from permission
        where permission.UserRecId == _userRecId
           && permission.Module    == _module;

    if (permission.RecId)
    {
        return permission.IsAllowed == NoYes::Yes;
    }

    select firstOnly RecId from anyRow
        where anyRow.UserRecId == _userRecId;

    return !anyRow.RecId
        && _module != HSMobileOpsModule::PO_CREATE
        && _module != HSMobileOpsModule::TO_CREATE
        && _module != HSMobileOpsModule::PO_CONFIRM;
}
